-- Crystalsong Forest: combat SmartAI for 21 creatures that cast no spell here and had no AI.
-- Rows from 5.4.8 (Legends of Azeroth), taken only where every event, action and target type is numbered the same in this core,
-- every spell is in the client data and 3.3.5 casts at least half of the same spells. Quest, summon and waypoint scripts are not included.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (30233,30238,30263,30265,30860,30861,30862,30863,30864,30865,31041,31123,31228,31229,31231,31233,31236,31393,31401,31404,32375) AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (30233,30238,30263,30265,30860,30861,30862,30863,30864,30865,31041,31123,31228,31229,31231,31233,31236,31393,31401,31404,32375);
